## 2. Plan de Pruebas Unitarias e Integración (Vitest)

Las pruebas unitarias validarán la lógica de cálculo financiero y tributario (incluyendo retenciones y redondeos DIAN), operando sobre mocks estrictos de Supabase RLS.

```typescript
// Archivo: src/features/pos/__tests__/pos-calculations.test.ts
import { describe, it, expect } from 'vitest';
import { posTransactionSchema } from '../schemas/pos-transaction.schema';

describe('SPEC-032: POS Financial & Tax Calculations (Vitest)', () => {
  it('debe validar exitosamente una transacción con impuestos y múltiples pagos', () => {
    const validTransaction = {
      tenantId: 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
      registerId: 'b1eebc99-9c0b-4ef8-bb6d-6bb9bd380a22',
      cashierId: 'c2eebc99-9c0b-4ef8-bb6d-6bb9bd380a33',
      items: [
        {
          productId: 'd3eebc99-9c0b-4ef8-bb6d-6bb9bd380a44',
          sku: 'PEZ-001',
          name: 'Salmón Fresco Premium (KG)',
          quantity: 2.5,
          unitPrice: 45000,
          taxRate: 19,
          discount: 0
        }
      ],
      payments: [
        { method: 'CASH', amount: 50000 },
        { method: 'NEQUI_DAVIPLATA', amount: 83375 }
      ],
      subtotal: 112500,
      taxesTotal: 21375,
      retentionTotal: 0,
      grandTotal: 133375
    };

    const result = posTransactionSchema.safeParse(validTransaction);
    expect(result.success).toBe(true);
  });

  it('debe fallar si el desglose de pagos no cuadra con el gran total (Desajuste financiero)', () => {
    const invalidTransaction = {
      tenantId: 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
      registerId: 'b1eebc99-9c0b-4ef8-bb6d-6bb9bd380a22',
      cashierId: 'c2eebc99-9c0b-4ef8-bb6d-6bb9bd380a33',
      items: [
        {
          productId: 'd3eebc99-9c0b-4ef8-bb6d-6bb9bd380a44',
          sku: 'PEZ-001',
          name: 'Salmón Fresco Premium (KG)',
          quantity: 1,
          unitPrice: 10000,
          taxRate: 0,
          discount: 0
        }
      ],
      payments: [
        { method: 'CASH', amount: 5000 } // Faltan 5000
      ],
      subtotal: 10000,
      taxesTotal: 0,
      retentionTotal: 0,
      grandTotal: 10000
    };

    const result = posTransactionSchema.safeParse(invalidTransaction);
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error.issues[0].message).toContain("La sumatoria de los pagos no coincide");
    }
  });
});
